import {axes,sourceLabels,validSize,round,measureRatio,fitFurniture,parseFurnitureJSON} from './core.mjs';
const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=value=>value===null?'—':Number(value).toLocaleString(undefined,{maximumFractionDigits:1});
const example=()=>({id:crypto.randomUUID(),name:'Example desk',dimensions:{width:140,depth:70,height:75},sources:{width:'example',depth:'example',height:'example'},listing:'',listingConfirmed:false});
let furniture=[example()],selected=furniture[0].id,photoMode='idle',referencePoints=[],measurePoints=[],measured=null,noticeTimer;
const photos=new Map();
const current=()=>furniture.find(o=>o.id===selected);
function announce(text){$('notice').textContent=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').textContent='',10000);}
function refreshInventory(){
  $('count').textContent=furniture.length;
  $('items').innerHTML=furniture.map(o=>`<button class="item ${o.id===selected?'active':''}" data-id="${o.id}" aria-pressed="${o.id===selected}"><svg viewBox="0 0 28 28" width="25" height="25" fill="none" aria-hidden="true"><path d="M3 8h22v11H3zM5 19v5m18-5v5M8 8V4h12v4" stroke="currentColor" stroke-width="1.2"/></svg><span><span class="item-name">${esc(o.name||'Untitled furniture')}</span><span class="item-meta">${format(o.dimensions.width)} × ${format(o.dimensions.depth)} cm</span></span></button>`).join('');
  $('items').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render();});
}
function refreshSources(){axes.forEach(a=>{const el=$('source-'+a);el.textContent=sourceLabels[current().sources[a]];el.classList.toggle('verified',current().sources[a]==='tape');});
  const values=Object.values(current().sources);
  $('object-source').textContent=values.every(v=>v==='example')?'Illustrative dimensions · replace with your own':values.every(v=>v==='tape')?'All dimensions tape-measured by you':values.includes('roomplan')?'Imported scan · review each dimension':'Review the source beneath each dimension';
}
function render(){
  const o=current();refreshInventory();$('name').value=o.name;
  $('dimension-fields').innerHTML=axes.map(a=>`<div class="dimension"><label for="dim-${a}">${a[0].toUpperCase()+a.slice(1)}<span>cm</span></label><input type="number" id="dim-${a}" min="0.1" max="100000" step="0.1" placeholder="—" value="${o.dimensions[a]??''}"><span class="source" id="source-${a}"></span></div>`).join('');
  axes.forEach(a=>$('dim-'+a).addEventListener('input',e=>{const v=e.target.value;o.dimensions[a]=v===''?null:Number(v);o.sources[a]='manual';o.listingConfirmed=false;$('listing-confirm').checked=false;refreshSources();refreshInventory();renderFit();}));
  $('listing-url').value=o.listing;$('listing-confirm').checked=!!o.listingConfirmed;updateListing();refreshSources();resetRuler();renderPhoto();renderFit();
}
function switchTab(tab){for(const name of ['photo','fit']){const active=tab===name;$(name+'-tab').setAttribute('aria-selected',active);$(name+'-tab').tabIndex=active?0:-1;$(name+'-panel').hidden=!active;}if(tab==='fit')renderFit();}
['photo','fit'].forEach(name=>{$(name+'-tab').onclick=()=>switchTab(name);$(name+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'photo':e.key==='End'?'fit':name==='photo'?'fit':'photo';switchTab(next);$(next+'-tab').focus();}};});
$('name').oninput=e=>{current().name=e.target.value;refreshInventory();};
$('add').onclick=()=>{const o={id:crypto.randomUUID(),name:'New furniture',dimensions:{width:null,depth:null,height:null},sources:{width:'manual',depth:'manual',height:'manual'},listing:'',listingConfirmed:false};furniture.push(o);selected=o.id;render();$('name').focus();$('name').select();announce('Furniture added. Upload a photo, or enter its dimensions.');};
$('example').onclick=()=>{const o=example();furniture.push(o);selected=o.id;render();announce('Loaded illustrative desk dimensions. These are not a scan.');};
$('remove').onclick=()=>{const old=current(),oldPhoto=photos.get(selected);furniture=furniture.filter(o=>o.id!==selected);if(oldPhoto)URL.revokeObjectURL(oldPhoto.url);photos.delete(selected);if(!furniture.length)furniture.push({id:crypto.randomUUID(),name:'New furniture',dimensions:{width:null,depth:null,height:null},sources:{width:'manual',depth:'manual',height:'manual'},listing:'',listingConfirmed:false});selected=furniture[0].id;render();announce(old.name+' removed.');};
$('scan-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw new Error('Please use a JSON file smaller than 10 MB.');const imported=parseFurnitureJSON(JSON.parse(await f.text()));furniture.push(...imported);selected=imported[0].id;render();announce('Imported '+imported.length+' furniture objects. RoomPlan axes map X to width, Z to depth, and Y to height; check the object orientation.');}catch(error){announce(error instanceof SyntaxError?'Could not read that JSON file. Please export a valid RoomPlan JSON.':error.message);}e.target.value='';};
function updateListing(){const a=$('open-listing');try{const u=new URL(current().listing);if(!['https:','http:'].includes(u.protocol))throw Error();a.href=u.href;a.hidden=false;}catch{a.removeAttribute('href');a.hidden=true;}}
$('listing-url').oninput=e=>{current().listing=e.target.value.trim();current().listingConfirmed=false;$('listing-confirm').checked=false;updateListing();};
$('listing-confirm').onchange=e=>{current().listingConfirmed=e.target.checked;};
$('use-listing').onclick=()=>{const o=current();try{const u=new URL(o.listing);if(!['https:','http:'].includes(u.protocol))throw Error();}catch{return announce('Enter a valid http or https product URL first.');}if(!o.listingConfirmed)return announce('Check the exact variant and assembled dimensions, then tick the confirmation.');if(!axes.every(a=>validSize(o.dimensions[a])))return announce('Enter all three positive dimensions from the listing first.');axes.forEach(a=>o.sources[a]='listing');refreshSources();renderFit();announce('Saved the listing as the dimension source. No page was fetched or independently verified.');};
$('confirm-tape').onclick=()=>{const o=current();if(!axes.every(a=>validSize(o.dimensions[a])))return announce('Enter valid width, depth, and height before confirming.');axes.forEach(a=>o.sources[a]='tape');refreshSources();renderFit();announce('All three dimensions marked as tape-measured by you.');};
async function loadPhoto(e){const file=e.target.files[0];if(!file)return;const id=selected;if(file.size>20*1024*1024){announce('Choose a photo smaller than 20 MB.');e.target.value='';return;}const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});if(!furniture.some(o=>o.id===id)){URL.revokeObjectURL(url);return;}const old=photos.get(id);if(old)URL.revokeObjectURL(old.url);photos.set(id,{url,width:1000,height:1000*img.naturalHeight/img.naturalWidth,name:file.name});if(id===selected){resetRuler();renderPhoto();}announce('Photo ready. Enter a known reference length, then mark its two endpoints.');}catch{URL.revokeObjectURL(url);announce('This image could not be opened. Try a JPEG, PNG, or WebP photo; convert HEIC to JPEG if needed.');}e.target.value='';}
$('photo-file').onchange=loadPhoto;$('camera-file').onchange=loadPhoto;
function renderPhoto(){const photo=photos.get(selected);$('photo-empty').hidden=!!photo;$('photo-svg').hidden=!photo;$('clear-photo').hidden=!photo;$('start-ruler').disabled=!photo;if(photo){$('photo-svg').setAttribute('viewBox',`0 0 ${photo.width} ${photo.height}`);$('photo-image').setAttribute('href',photo.url);$('photo-image').setAttribute('width',photo.width);$('photo-image').setAttribute('height',photo.height);}else{$('photo-image').removeAttribute('href');}drawLines();}
$('clear-photo').onclick=()=>{const photo=photos.get(selected);if(photo)URL.revokeObjectURL(photo.url);photos.delete(selected);resetRuler();renderPhoto();announce('Photo cleared. Previously applied dimensions are preserved.');};
function resetRuler(){photoMode='idle';referencePoints=[];measurePoints=[];measured=null;$('ruler-result').hidden=true;$('photo-svg').classList.remove('measuring');$('ruler-status').textContent=photos.has(selected)?'Set a known reference length, then mark two reference endpoints.':'Choose a photo to use the ruler. You can also enter dimensions directly.';$('start-ruler').textContent='Set reference points';drawLines();}
function startRuler(){if(!photos.has(selected))return;if(!validSize($('reference').value))return announce('Enter a positive reference length first.');resetRuler();photoMode='reference';$('photo-svg').classList.add('measuring');$('ruler-status').textContent='1 / 2 · Click the first endpoint of your known reference.';$('start-ruler').textContent='Restart reference';}
$('start-ruler').onclick=startRuler;$('reset-points').onclick=startRuler;
$('reference').oninput=()=>{if(referencePoints.length===2&&measurePoints.length===2)computeMeasurement();};
$('photo-svg').addEventListener('click',e=>{if(photoMode==='idle'||photoMode==='done')return;const svg=$('photo-svg'),photo=photos.get(selected),matrix=svg.getScreenCTM();if(!matrix||!photo)return;const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());if(pt.x<0||pt.x>photo.width||pt.y<0||pt.y>photo.height)return;const p={x:pt.x,y:pt.y};if(photoMode==='reference'){referencePoints.push(p);if(referencePoints.length===1)$('ruler-status').textContent='1 / 2 · Click the other endpoint of your known reference.';else{if(Math.hypot(referencePoints[0].x-p.x,referencePoints[0].y-p.y)<5){referencePoints.pop();announce('Reference points are too close. Choose a longer reference.');return;}photoMode='measurement';$('ruler-status').textContent='2 / 2 · Click the first endpoint of the furniture dimension.';}}else{measurePoints.push(p);if(measurePoints.length===1)$('ruler-status').textContent='2 / 2 · Click the other endpoint of the furniture dimension.';else{photoMode='done';$('photo-svg').classList.remove('measuring');computeMeasurement();}}drawLines();});
function computeMeasurement(){try{measured=measureRatio(referencePoints,measurePoints,Number($('reference').value));$('measured-value').textContent=format(measured)+' cm';$('ruler-result').hidden=false;$('ruler-status').textContent='Blue = known reference. Orange = measured length. Confirm both are on the same plane.';}catch(e){measured=null;$('ruler-result').hidden=true;announce(e.message);}}
function drawLines(){const svg=$('photo-svg');const scale=photos.get(selected)?Math.max(1,Math.min(5,1000/(svg.clientWidth||500))):2;let html='';[[referencePoints,'#2563df','Reference'],[measurePoints,'#ce601c','Measure']].forEach(([points,color,label])=>{if(points.length===2){html+=`<line x1="${points[0].x}" y1="${points[0].y}" x2="${points[1].x}" y2="${points[1].y}" stroke="${color}" stroke-width="${2.5*scale}"/>`;}points.forEach((p,i)=>{html+=`<circle cx="${p.x}" cy="${p.y}" r="${5*scale}" fill="${color}" stroke="white" stroke-width="${1.5*scale}"/><text x="${p.x+10*scale}" y="${p.y-10*scale}" fill="${color}" stroke="white" paint-order="stroke" stroke-width="${3*scale}" font-family="sans-serif" font-size="${13*scale}">${label} ${i+1}</text>`;});});$('photo-lines').innerHTML=html;}
$('apply-measurement').onclick=()=>{if(!validSize(measured))return;const axis=$('axis').value;current().dimensions[axis]=measured;current().sources[axis]='photo';current().listingConfirmed=false;$('listing-confirm').checked=false;$('dim-'+axis).value=measured;refreshSources();refreshInventory();renderFit();announce(axis[0].toUpperCase()+axis.slice(1)+' updated to '+format(measured)+' cm as a photo estimate.');};
function renderFit(){const o=current(),space={width:Number($('space-width').value),depth:Number($('space-depth').value)},margin=Number($('margin').value),rotated=$('rotate').checked;let result=fitFurniture(o.dimensions,space,margin,rotated);if($('margin').value==='')result={status:'missing'};const panel=$('fit-result');panel.className='fit-result';if(result.status==='missing'){panel.classList.add('warning');panel.textContent='Enter furniture width and depth, positive space dimensions, and a clearance allowance.';$('footprint').innerHTML='<text x="350" y="210" text-anchor="middle" fill="#626b78" font-size="16">Enter dimensions to see a footprint.</text>';return;}
  const s=Math.min(530/Math.max(space.width,result.width),280/Math.max(space.depth,result.depth)),ox=80,oy=60,sw=space.width*s,sd=space.depth*s,fw=result.width*s,fd=result.depth*s;
  $('footprint').innerHTML=`<defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#e5eaf1" stroke-width=".6"/></pattern></defs><rect width="700" height="430" fill="url(#grid)"/><rect x="${ox}" y="${oy}" width="${sw}" height="${sd}" fill="#fff" stroke="#758396" stroke-width="2" stroke-dasharray="7 5"/><rect x="${ox}" y="${oy}" width="${fw}" height="${fd}" fill="${result.status==='too-large'?'#f2d9d3':'#dbe7fc'}" fill-opacity=".85" stroke="${result.status==='too-large'?'#aa5645':'#3868ba'}" stroke-width="2"/><text x="${ox}" y="35" fill="#475468" font-size="15">Available: ${format(space.width)} × ${format(space.depth)} cm</text><text x="${ox}" y="${oy+Math.max(sd,fd)+32}" fill="#2758cc" font-size="15">Furniture: ${format(result.width)} × ${format(result.depth)} cm${rotated?' · rotated':''}</text><text x="${ox}" y="400" fill="#626b78" font-size="13">Top view · furniture aligned to the upper-left corner</text>`;
  let title=result.status==='fits'?'Within the entered dimensions':result.status==='tight'?'Fits geometrically, but clearance is tight':'Too large for this space';
  if(result.status==='too-large')panel.classList.add('fail');if(result.status==='tight')panel.classList.add('warning');
  const verified=['width','depth'].every(a=>o.sources[a]==='tape');
  panel.innerHTML=`<strong>${title}</strong>${result.spareWidth<0?'Exceeds width by '+format(-result.spareWidth):'Spare width: '+format(result.spareWidth)} cm · ${result.spareDepth<0?'exceeds depth by '+format(-result.spareDepth):'spare depth: '+format(result.spareDepth)} cm.<br><span>${verified?'Furniture footprint marked as tape-measured by you.':'Furniture dimensions include estimates or unverified values.'} Verify the available space before relying on a tight fit.</span>`;
}
['space-width','space-depth','margin','rotate'].forEach(id=>$(id).oninput=renderFit);
function exported(){return {format:'redesign-furniture-v1',units:'cm',exportedAt:new Date().toISOString(),furniture:furniture.map(o=>({...o,dimensions:{...o.dimensions},sources:{...o.sources}})),notes:'Photos are not included. Photo measurements are uncorrected pixel ratios. Source labels reflect user actions, not independent verification.'};}
$('export').onclick=()=>{if(furniture.some(o=>axes.some(a=>o.dimensions[a]!==null&&!validSize(o.dimensions[a]))))return announce('Fix invalid dimensions before exporting. Blank dimensions are allowed.');const url=URL.createObjectURL(new Blob([JSON.stringify(exported(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='redesign-furniture.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Exported furniture dimensions and sources. Photos are not included.');};
render();
// Expose the same read and fit operations to browsers that support WebMCP.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_furniture_dimensions',title:'Read furniture dimensions',description:'Read current furniture dimensions in centimeters and their provenance. Does not include photos.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>exported()},{name:'configure_fit_check',title:'Configure furniture fit check',description:'Select furniture and update the visible footprint comparison. This is an estimated rectangular fit check, not a guarantee.',inputSchema:{type:'object',properties:{furnitureId:{type:'string'},widthCm:{type:'number',exclusiveMinimum:0,maximum:10000},depthCm:{type:'number',exclusiveMinimum:0,maximum:10000},clearanceCm:{type:'number',minimum:0,maximum:1000},rotate:{type:'boolean'}},required:['furnitureId','widthCm','depthCm','clearanceCm','rotate'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||!furniture.some(o=>o.id===input.furnitureId)||!validSize(input.widthCm)||input.widthCm>10000||!validSize(input.depthCm)||input.depthCm>10000||typeof input.clearanceCm!=='number'||!Number.isFinite(input.clearanceCm)||input.clearanceCm<0||input.clearanceCm>1000||typeof input.rotate!=='boolean')throw new Error('Invalid furniture ID or space dimensions.');selected=input.furnitureId;render();$('space-width').value=input.widthCm;$('space-depth').value=input.depthCm;$('margin').value=input.clearanceCm;$('rotate').checked=input.rotate;switchTab('fit');return fitFurniture(current().dimensions,{width:input.widthCm,depth:input.depthCm},input.clearanceCm,input.rotate);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
